  const benchmark:GoldBenchmark={id:GOLD_BENCHMARK,organization_id:'org',establishment_id:'shabu',source_generation_id:GOLD_SOURCE,source_analysis_version:7,status:'completed',benchmark_type:'themes_phase2',repeat_count:3,served_models:['jev-fixture'],decisions:reviews.map((r,i)=>({review_id:r.id,repetitions:Array.from({length:3},()=>i<95?{themes:Object.fromEntries(GOLD_KEYS.map(theme=>{const choice=theme==='food_quality'&&i<80||theme==='friendly_staff'&&i<62||theme==='attentiveness'&&i<70||theme==='professionalism'&&i<60?'positive':'absent';return [theme,{choice,probabilities:{absent:choice==='absent'?1:0,positive:choice==='positive'?1:0,negative:0,both:0}}]})) as NonNullable<GoldBenchmark['decisions'][number]['repetitions'][number]>['themes']}:null)}))}
